#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <math.h>

char* program_name;

char buffer[1024*1024];

int curr_date_time_line;
char curr_date[1024];
char curr_time[1024];
char prev_date[1024];
char prev_time[1024];

char best_drop_date[1024];
char best_drop_time[1024];
char best_drop_next_date[1024];
char best_drop_next_time[1024];
double best_drop_delta;
int best_drop_line = -1;


void print_usage() {
  fprintf(stderr, "%s: usage: %s input.csv output_part1.csv output_part2.csv\n", program_name, program_name);
}

char* skip_space(char* str) {
  while (*str == ' ') str++;
  return str;
}

double convert_from_db(double db) {
  return pow(10.0, db/10.0);
}

double convert_to_db(double value) {
  return log10(value)*10.0;
}

int main(int argc, char** argv) {

  program_name = argv[0];

  int ret = 0;

  if (argc != 4) {
    print_usage();
    ret = 1;
  } else {

    char* input_file_name = argv[1];
    char* output_part1_file_name = argv[2];
    char* output_part2_file_name = argv[3];

    FILE* input_file = fopen(input_file_name, "r");
    if (!input_file) {
      fprintf(stderr, "%s: could not open input file %s: %s\n", program_name, input_file_name, strerror(errno));
      ret = 2;
    } else {

      int line_number = 0;
      double prev_sum_samples = -1.0;
      double curr_sum_samples = 0.0;

      for (;;) {

        if (fgets(buffer, sizeof(buffer), input_file) == NULL) {

          if (prev_sum_samples >= 0.0) {

            double delta = curr_sum_samples - prev_sum_samples;
            if (best_drop_line < 0 || delta < best_drop_delta) {
              best_drop_delta = delta;
              best_drop_line = curr_date_time_line;
              snprintf(best_drop_date, sizeof(best_drop_date), "%s", curr_date);
              snprintf(best_drop_time, sizeof(best_drop_time), "%s", curr_time);
            }
          }

          break;
        }

        char* date_str = strtok(buffer, ",");
        if (!date_str) {
          fprintf(stderr, "%s: Error in file %s, line %d: Expected date\n", program_name, input_file_name, line_number);
          ret = 3;
          break;
        }

        date_str = skip_space(date_str);

        char* time_str = strtok(NULL, ",");
        if (!time_str) {
          fprintf(stderr, "%s: Error in file %s, line %d: Expected time\n", program_name, input_file_name, line_number);
          ret = 3;
          break;
        }

        time_str = skip_space(time_str);

        char* lower_freq_str = strtok(NULL, ",");
        if (!lower_freq_str) {
          fprintf(stderr, "%s: Error in file %s, line %d: Expected lower_freq\n", program_name, input_file_name, line_number);
          ret = 3;
          break;
        }
        lower_freq_str = skip_space(lower_freq_str);

        //double lower_freq = strtod(lower_freq_str, NULL);

        char* upper_freq_str = strtok(NULL, ",");
        if (!upper_freq_str) {
          fprintf(stderr, "%s: Error in file %s, line %d: Expected upper_freq\n", program_name, input_file_name, line_number);
          ret = 3;
          break;
        }
        upper_freq_str = skip_space(upper_freq_str);

        //double upper_freq = strtod(upper_freq_str, NULL);

        char* bin_size_str = strtok(NULL, ",");
        if (!bin_size_str) {
          fprintf(stderr, "%s: Error in file %s, line %d: Expected bin_size\n", program_name, input_file_name, line_number);
          ret = 3;
          break;
        }
        bin_size_str = skip_space(bin_size_str);

        //double bin_size = strtod(bin_size_str, NULL);

        char* num_samples_str = strtok(NULL, ",");
        if (!num_samples_str) {
          fprintf(stderr, "%s: Error in file %s, line %d: Expected num_samples\n", program_name, input_file_name, line_number);
          ret = 3;
          break;
        }
        num_samples_str = skip_space(num_samples_str);

        // disregarding num_samples.
        //int num_samples = atoi(num_samples_str);

        if (line_number == 0) {

          snprintf(curr_date, sizeof(curr_date), "%s", date_str);
          snprintf(curr_time, sizeof(curr_time), "%s", time_str);
          curr_date_time_line = line_number;

        } else if (strcmp(curr_date, date_str) || strcmp(curr_time, time_str)) {

          if (prev_sum_samples >= 0.0) {

            double delta = curr_sum_samples - prev_sum_samples;
            if (best_drop_line < 0 || delta < best_drop_delta) {
              best_drop_delta = delta;
              best_drop_line = curr_date_time_line;
              snprintf(best_drop_date, sizeof(best_drop_date), "%s", curr_date);
              snprintf(best_drop_time, sizeof(best_drop_time), "%s", curr_time);
            }
          }

          prev_sum_samples = curr_sum_samples;
          curr_sum_samples = 0.0;
          curr_date_time_line = line_number;

          snprintf(prev_date, sizeof(prev_date), "%s", curr_date);
          snprintf(prev_time, sizeof(prev_time), "%s", curr_time);
          snprintf(curr_date, sizeof(curr_date), "%s", date_str);
          snprintf(curr_time, sizeof(curr_time), "%s", time_str);

        }

        for (;;) {
          char* sample_str = strtok(NULL, ",");
          if (!sample_str) break;
          sample_str = skip_space(sample_str);

          double sample_db = strtod(sample_str, NULL);
          double sample_linear = convert_from_db(sample_db);

          curr_sum_samples += sample_linear;
        }

        line_number++;
      }

      fclose(input_file);

      // Should normalize the delta here by the number of samples, but it's constant for each row anyways.
      fprintf(stderr, "%s: best_drop: line=%d, date=%s, time=%s, delta=%lf, drop_db=%lf\n",
          program_name, best_drop_line, best_drop_date, best_drop_time,
          best_drop_delta, convert_to_db(-best_drop_delta));

      input_file = fopen(input_file_name, "r");
      if (!input_file) {
        fprintf(stderr, "%s: could not open input file %s: %s\n", program_name, input_file_name, strerror(errno));
        ret = 2;
      } else {

        FILE* output_part1_file = fopen(output_part1_file_name, "w");
        if (!output_part1_file) {
          fprintf(stderr, "%s: could not open output file %s: %s\n", program_name, output_part1_file_name, strerror(errno));
          ret = 4;
        } else {

          int line_number = 0;
          for (;;) {

            if (line_number >= best_drop_line) break;

            if (fgets(buffer, sizeof(buffer), input_file) == NULL) break;

            fprintf(output_part1_file, "%s", buffer);
            line_number++;
          }

          fclose(output_part1_file);

          FILE* output_part2_file = fopen(output_part2_file_name, "w");
          if (!output_part2_file) {
            fprintf(stderr, "%s: could not open output file %s: %s\n", program_name, output_part2_file_name, strerror(errno));
            ret = 5;
          } else {

            while (fgets(buffer, sizeof(buffer), input_file) != NULL) {
              fprintf(output_part2_file, "%s", buffer);
            }

            fclose(output_part2_file);
          }
        }

        fclose(input_file);
      }
    }
  }

  return ret;
}
